// RGBA(알파 255)로 펼친다
export function rgbaOf(o){ const rgb=zlib.gunzipSync(Buffer.from(o.rgb,'base64')), px=new Uint8ClampedArray(32*32*4); for(let i=0,j=0;i<32*32;i++,j+=3){ px[i*4]=rgb[j]; px[i*4+1]=rgb[j+1]; px[i*4+2]=rgb[j+2]; px[i*4+3]=255; } return px; }
